BEGIN;
CREATE TABLE mealplan.plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),starts_on date NOT NULL,ends_on date NOT NULL,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),CHECK(ends_on>=starts_on));
CREATE TABLE mealplan.meals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),plan_id uuid NOT NULL,planned_on date NOT NULL,meal_slot text NOT NULL DEFAULT 'dinner' CHECK(meal_slot IN('breakfast','lunch','dinner','snack')),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),servings numeric(18,6) NOT NULL DEFAULT 4 CHECK(servings>0),recipe_reference uuid,notes text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,plan_id) REFERENCES mealplan.plans(household_id,id));
CREATE INDEX meals_plan ON mealplan.meals(household_id,plan_id,planned_on);
GRANT USAGE ON SCHEMA mealplan TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA mealplan TO household_app;
COMMIT;
